import json,os,re,collections
g=json.load(open('/tmp/ajcr_graph.json'))
print("total nodes:",len(g))
os.chdir('/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild')
mods={}
for dp,_,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'): mods[os.path.join(dp,f)]=os.path.join(dp,f)[:-5].replace('/','.')
mods['AlgebraicJacobian.lean']='AlgebraicJacobian'
imp=re.compile(r'^\s*import\s+([A-Za-z0-9_.]+)',re.M)
name2p={v:k for k,v in mods.items()}
edges={m:[x for x in imp.findall(open(p,encoding='utf-8',errors='replace').read()) if x in name2p] for p,m in mods.items()}
seen={'AlgebraicJacobian'};q=collections.deque(seen)
while q:
    c=q.popleft()
    for n in edges.get(c,[]):
        if n not in seen: seen.add(n);q.append(n)
rootedfiles={name2p[m] for m in seen}
cnt=collections.Counter()
unrooted_nodes=[];missing_nodes=[]
for n in g:
    f=n.get('file')
    if not f: cnt['no-file']+=1; continue
    if f not in mods:
        missing_nodes.append((n.get('id'),n.get('lean_status'),f,n.get('title')))
        continue
    if f not in rootedfiles:
        unrooted_nodes.append((n.get('id'),n.get('lean_status'),f,n.get('title')))
print("nodes with no file field:",cnt['no-file'])
print("nodes whose FILE DOES NOT EXIST on disk:",len(missing_nodes))
print("   lean_ok among them:",sum(1 for x in missing_nodes if x[1]=='lean_ok'))
byf=collections.Counter(x[2] for x in missing_nodes)
for f,c in byf.most_common(15): print("      ",c,f)
print("nodes over files that EXIST but are UNROOTED:",len(unrooted_nodes))
print("   lean_ok among them:",sum(1 for x in unrooted_nodes if x[1]=='lean_ok'))
byf2=collections.Counter(x[2] for x in unrooted_nodes)
for f,c in byf2.most_common(30): print("      ",c,f)
print()
print("TOTAL nodes the build never sees (missing-file + unrooted):",len(missing_nodes)+len(unrooted_nodes))
print("   of which lean_ok:",sum(1 for x in missing_nodes+unrooted_nodes if x[1]=='lean_ok'))
import collections as C
print("   status breakdown:",C.Counter(x[1] for x in missing_nodes+unrooted_nodes))
